import { HistoricalDocument } from '../../types';

export const codigoManuCapitulo7: HistoricalDocument = {
  id: 'codigo-manu-capitulo-7',
  title: 'Capítulo VII',
  subtitle: 'Dos Deveres do Rei',
  date: 'c. 200 a.C. – 200 d.C.',
  era: 'Índia Antiga',
  language: 'Sânscrito',
  description: 'Expõe as obrigações do rei, a administração do reino, a guerra e a política exterior.',
  parentCollectionId: 'codigo-de-manu',
  sections: [
    {
      id: 'versos',
      title: 'Capítulo VII',
      type: 'articles',
      articles: [
        { id: 'cm-7-1', number: 'Verso 1', text: `Declararei os deveres dos reis, (e) mostrarei como um rei deve conduzir-se, como ele foi criado, e como (ele pode obter) o mais alto sucesso.` },
        { id: 'cm-7-2', number: 'Verso 2', text: `Um *Kshatriya*, que recebeu de acordo com a regra o sacramento prescrito pelo Veda, deve proteger devidamente todo este (mundo).` },
        { id: 'cm-7-3', number: 'Verso 3', text: `Pois, quando estas criaturas, estando sem um rei, através do medo se dispersaram em todas as direções, o Senhor criou um rei para a proteção de toda esta (criação),` },
        { id: 'cm-7-4', number: 'Verso 4', text: `Tomando (para esse propósito) partículas eternas de Indra, do Vento, de Yama, do Sol, do Fogo, de Varuna, da Lua, e do Senhor da riqueza (Kubera).` },
        { id: 'cm-7-5', number: 'Verso 5', text: `Porque um rei foi formado de partículas desses senhores dos deuses, ele portanto ultrapassa todas as criaturas criadas em esplendor;` },
        { id: 'cm-7-6', number: 'Verso 6', text: `E, como o sol, ele queima olhos e corações; nem pode ninguém na terra sequer fixar o olhar nele.` },
        { id: 'cm-7-7', number: 'Verso 7', text: `Através do seu poder (sobrenatural) ele é Fogo e Vento, ele é Sol e Lua, ele é o Senhor da justiça (Yama), ele é Kubera, ele é Varuna, ele é o grande Indra.` },
        { id: 'cm-7-8', number: 'Verso 8', text: `Mesmo um rei infante não deve ser desprezado, (sob a ideia) de que ele é um (mero) mortal; pois ele é uma grande deidade em forma humana.` },
        { id: 'cm-7-9', number: 'Verso 9', text: `O fogo queima apenas um homem, se ele descuidadamente se aproxima dele, (mas) o fogo da (ira) de um rei consome a família (inteira), junto com o seu gado e o seu tesouro de propriedades.` },
        { id: 'cm-7-10', number: 'Verso 10', text: `Tendo considerado totalmente o propósito, o (seu) poder, e o lugar e o tempo, ele assume alternadamente muitas formas (diferentes) para a completa obtenção da justiça.` },
        { id: 'cm-7-11', number: 'Verso 11', text: `Ele, em cujo favor reside Padma, a deusa da fortuna, em cuja bravura habita a vitória, em cuja ira permanece a morte, é formado do esplendor de todos (os deuses).` },
        { id: 'cm-7-12', number: 'Verso 12', text: `O (homem), que em sua extrema tolice o odeia, indubitavelmente perecerá; pois o rei rapidamente decide destruir tal (homem).` },
        { id: 'cm-7-13', number: 'Verso 13', text: `Que nenhum (homem), portanto, transgrida a lei que favorece, nem (as suas ordens) que infligem dor naqueles em desfavor.` },
        { id: 'cm-7-14', number: 'Verso 14', text: `Pelo bem do (rei), o Senhor criou antigamente o seu próprio filho, a Punição, o protetor de todas as criaturas, (uma encarnação da) lei, formado da glória de Brahman.` },
        { id: 'cm-7-15', number: 'Verso 15', text: `Através do medo dele, todas as criaturas criadas, tanto as imóveis quanto as móveis, permitem-se ser desfrutadas e não se desviam dos seus deveres.` },
        { id: 'cm-7-16', number: 'Verso 16', text: `Tendo considerado totalmente o tempo e o lugar (da ofensa), a força e o conhecimento (do ofensor), que ele inflija justamente aquela (punição) aos homens que agem injustamente.` },
        { id: 'cm-7-17', number: 'Verso 17', text: `A Punição é (na realidade) o rei (e) o macho, que é o gerente dos assuntos, que é o governante, e que é chamado de fiador da obediência das quatro ordens à lei.` },
        { id: 'cm-7-18', number: 'Verso 18', text: `A punição sozinha governa todas as criaturas criadas, a punição sozinha as protege, a punição vigia sobre elas enquanto dormem; os sábios declaram a punição (como sendo idêntica à) lei.` },
        { id: 'cm-7-19', number: 'Verso 19', text: `Se (a punição) é adequadamente infligida após (devida) consideração, ela faz todas as pessoas felizes; mas infligida sem consideração, ela destrói tudo.` },
        { id: 'cm-7-20', number: 'Verso 20', text: `Se o rei não infligisse, sem se cansar, a punição naqueles dignos de serem punidos, os mais fortes assariam os mais fracos, como peixes num espeto;` },
        { id: 'cm-7-21', number: 'Verso 21', text: `O corvo comeria o bolo sacrificial e o cão lamberia as iguarias sacrificiais, e a propriedade não permaneceria com ninguém, os mais baixos (usurpariam o lugar dos) mais altos.` },
        { id: 'cm-7-22', number: 'Verso 22', text: `O mundo inteiro é mantido em ordem pela punição, pois um homem sem culpa é difícil de encontrar; através do medo da punição, o mundo inteiro rende os gozos (que deve).` },
        { id: 'cm-7-23', number: 'Verso 23', text: `Os deuses, os *Danavas*, os *Gandharvas*, os *Rakshasas*, as deidades pássaro e serpente rendem os gozos (devidos por eles) apenas, se forem atormentados pelo (medo da) punição.` },
        { id: 'cm-7-24', number: 'Verso 24', text: `Todas as castas (*varna*) seriam corrompidas (por mistura), todas as barreiras seriam rompidas, e todos os homens se enfureceriam (uns contra os outros) em consequência de erros em relação à punição.` },
        { id: 'cm-7-25', number: 'Verso 25', text: `Mas onde a Punição com uma tonalidade negra e olhos vermelhos caminha, destruindo pecadores, lá os súditos não são perturbados, desde que aquele que a inflige discirna bem.` },
        { id: 'cm-7-26', number: 'Verso 26', text: `Eles declaram ser esse rei um justo aplicador de punição, que é verdadeiro, que age após devida consideração, que é sábio, e que conhece (o respectivo valor da) virtude, prazer, e riqueza.` },
        { id: 'cm-7-27', number: 'Verso 27', text: `Um rei que inflige (punição) adequadamente, prospera com respeito a (esses) três (meios de felicidade); mas aquele que é voluptuoso, parcial, e enganador será destruído, mesmo através da punição (injusta) (que ele inflige).` },
        { id: 'cm-7-28', number: 'Verso 28', text: `A punição (possui) um esplendor muito brilhante, e é difícil de ser administrada por homens com mentes não aprimoradas; ela abate o rei que se desvia do seu dever, juntamente com os seus parentes.` },
        { id: 'cm-7-29', number: 'Verso 29', text: `A seguir, ela afligirá os seus castelos, os seus territórios, o mundo inteiro junto com a (criação) móvel e imóvel, da mesma forma os sábios e os deuses, que (na falta de oferendas) ascendem ao céu.` },
        { id: 'cm-7-30', number: 'Verso 30', text: `(A punição) não pode ser infligida justamente por alguém que não tem assistente, (nem) por um tolo, (nem) por um homem cobiçoso, (nem) por alguém cuja mente não é aprimorada, (nem) por alguém viciado em prazeres sensuais.` },
        { id: 'cm-7-31', number: 'Verso 31', text: `Por aquele que é puro (e) fiel à sua promessa, que age de acordo com os Institutos (da lei sagrada), que tem bons assistentes e é sábio, a punição pode ser (justamente) infligida.` },
        { id: 'cm-7-32', number: 'Verso 32', text: `Que ele aja com justiça no seu próprio domínio, com rigor castigue os seus inimigos, comporte-se sem duplicidade para com os seus amigos, e seja leniente para com os *Brahmanas*.` },
        { id: 'cm-7-33', number: 'Verso 33', text: `A fama de um rei que se comporta assim, ainda que ele subsista de respigas, espalha-se no mundo, como uma gota de óleo na água.` },
        { id: 'cm-7-34', number: 'Verso 34', text: `Mas a fama de um rei que age de maneira contrária e que não se subjuga, diminui em extensão entre os homens como uma gota de manteiga clarificada na água.` },
        { id: 'cm-7-35', number: 'Verso 35', text: `O rei foi criado (para ser) o protetor das castas (*varna*) e ordens, que, todos de acordo com a sua posição, cumprem os seus vários deveres.` },
        { id: 'cm-7-36', number: 'Verso 36', text: `O que quer que deva ser feito por ele e pelos seus servos para a proteção do seu povo, isso eu declararei totalmente a vós na devida ordem.` },
        { id: 'cm-7-37', number: 'Verso 37', text: `Que o rei, após levantar-se cedo de manhã, adore os *Brahmanas* que são bem versados na tríplice ciência sagrada e instruídos (em política), e siga o seu conselho.` },
        { id: 'cm-7-38', number: 'Verso 38', text: `Que ele adore diariamente *Brahmanas* idosos que conhecem o Veda e são puros; pois aquele que sempre adora homens idosos, é honrado até mesmo por *Rakshasas*.` },
        { id: 'cm-7-39', number: 'Verso 39', text: `Que ele, embora já possa ser modesto, aprenda constantemente a modéstia com eles; pois um rei que é modesto nunca perece.` },
        { id: 'cm-7-40', number: 'Verso 40', text: `Por falta de modéstia, muitos reis pereceram, juntamente com os seus pertences; através da modéstia, até mesmo eremitas na floresta ganharam reinos.` },
        { id: 'cm-7-41', number: 'Verso 41', text: `Por falta de humildade, Vena pereceu, da mesma forma o rei Nahusha, Sudas, o filho de Pigavana, Sumukha, e Nemi.` },
        { id: 'cm-7-42', number: 'Verso 42', text: `Mas pela humildade Prithu e Manu ganharam soberania, Kubera a posição de Senhor da riqueza, e o filho de Gadhi o posto de um *Brahmana*.` },
        { id: 'cm-7-43', number: 'Verso 43', text: `Daqueles versados nos três Vedas, que ele aprenda a tríplice (ciência sagrada), a ciência primordial do governo, a ciência da dialética, e o conhecimento da Alma (suprema); do povo, (a teoria de) (vários) ofícios e profissões.` },
        { id: 'cm-7-44', number: 'Verso 44', text: `Dia e noite ele deve esforçar-se arduamente para conquistar os seus sentidos; pois (apenas) ele que conquistou os seus próprios sentidos, pode manter os seus súditos em obediência.` },
        { id: 'cm-7-45', number: 'Verso 45', text: `Que ele evite cuidadosamente os dez vícios, que brotam do amor ao prazer, e os oito, que procedem da ira, os quais (todos) terminam em miséria.` },
        { id: 'cm-7-46', number: 'Verso 46', text: `Pois um rei que está apegado aos vícios que brotam do amor ao prazer, perde a sua riqueza e a sua virtude, mas (aquele que se entrega) àqueles decorrentes da ira, (perde) até mesmo a sua vida.` },
        { id: 'cm-7-47', number: 'Verso 47', text: `Caça, jogos de azar, dormir de dia, criticismo, (excesso com) mulheres, embriaguez, (um amor desordenado por) dança, canto, e música, e viagens inúteis são o conjunto décuplo (de vícios) que brotam do amor ao prazer.` },
        { id: 'cm-7-48', number: 'Verso 48', text: `Fofoca, violência, traição, inveja, calúnia, apreensão (injusta) de propriedade, insulto, e agressão são o conjunto óctuplo (de vícios) produzidos pela ira.` },
        { id: 'cm-7-49', number: 'Verso 49', text: `Aquela ganância que todos os homens sábios declaram ser a raiz mesmo de ambos estes (conjuntos), que ele a conquiste cuidadosamente; ambos os conjuntos (de vícios) são produzidos por isso.` },
        { id: 'cm-7-50', number: 'Verso 50', text: `Bebida, dados, mulheres, e caça, estes quatro (que foram enumerados) em sucessão, ele deve saber que são os mais perniciosos no conjunto que brota do amor ao prazer.` },
        { id: 'cm-7-51', number: 'Verso 51', text: `Causar dano corporal, insultar, e a apreensão de propriedade, estes três ele deve saber que são os mais perniciosos no conjunto produzido pela ira.` },
        { id: 'cm-7-52', number: 'Verso 52', text: `Um (rei) autocontrolado deve saber que neste conjunto de sete, que prevalece em toda parte, cada vício nomeado anteriormente é mais abominável (do que os nomeados posteriormente).` },
        { id: 'cm-7-53', number: 'Verso 53', text: `(Numa comparação) entre o vício e a morte, o vício é declarado ser mais pernicioso; um homem vicioso afunda no mais profundo (inferno), aquele que morre, livre do vício, ascende ao céu.` },
        { id: 'cm-7-54', number: 'Verso 54', text: `Que ele nomeie sete ou oito ministros cujos ancestrais tenham sido servos reais, que sejam versados nas ciências, heróis habilidosos no uso de armas e descendentes de famílias (nobres) e que tenham sido testados.` },
        { id: 'cm-7-55', number: 'Verso 55', text: `Mesmo um empreendimento fácil (em si mesmo) é (às vezes) difícil de ser realizado por um único homem; quão (mais difícil é para um rei), especialmente (se ele) não tiver assistente, (governar) um reino que rende grandes receitas.` },
        { id: 'cm-7-56', number: 'Verso 56', text: `Que ele considere diariamente com eles os (negócios) ordinários (referentes a) paz e guerra, (os quatro assuntos chamados) *sthana*, a receita, a (maneira de) proteger (a si mesmo e ao seu reino), e a santificação de seus ganhos (por dádivas piedosas).` },
        { id: 'cm-7-57', number: 'Verso 57', text: `Tendo (primeiro) averiguado a opinião de cada (ministro) separadamente e (então as visões) de todos juntos, que ele faça o que é (mais) benéfico para si nos seus assuntos.` },
        { id: 'cm-7-58', number: 'Verso 58', text: `Mas com o mais distinto entre todos eles, um *Brahmana* instruído, que o rei delibere sobre os assuntos mais importantes que se relacionam com as seis medidas da política real.` },
        { id: 'cm-7-59', number: 'Verso 59', text: `Que ele, cheio de confiança, confie sempre a esse (oficial) todos os negócios; tendo tomado a sua resolução final com ele, que ele depois comece a agir.` },
        { id: 'cm-7-60', number: 'Verso 60', text: `Ele deve também nomear outros oficiais, (homens) de integridade, (que sejam) sábios, firmes, bem capazes de coletar dinheiro, e bem testados.` },
        { id: 'cm-7-61', number: 'Verso 61', text: `Tantas pessoas quantas a devida realização dos seus negócios exigir, tantos (homens) habilidosos e inteligentes, livres da preguiça, que ele nomeie.` },
        { id: 'cm-7-62', number: 'Verso 62', text: `Entre eles, que ele empregue os corajosos, os habilidosos, os de alto nascimento, e os honestos em (cargos para a coleta de) receitas, (ex.) em minas, manufaturas, e armazéns, (mas) os tímidos no interior do seu palácio.` },
        { id: 'cm-7-63', number: 'Verso 63', text: `Que ele também nomeie um embaixador que seja versado em todas as ciências, que entenda dicas, expressões faciais e gestos, que seja honesto, habilidoso, e de família (nobre).` },
        { id: 'cm-7-64', number: 'Verso 64', text: `(Tal) embaixador é recomendado a um rei (que seja) leal, honesto, habilidoso, possuidor de boa memória, que conheça o lugar e o tempo (apropriados para ação, que seja) bonito, destemido, e eloquente.` },
        { id: 'cm-7-65', number: 'Verso 65', text: `O exército depende do oficial (colocado no seu comando), o devido controle (dos súditos) depende do exército, o tesouro e o (governo do) reino dependem do rei, a paz e o seu oposto (guerra) dependem do embaixador.` },
        { id: 'cm-7-66', number: 'Verso 66', text: `Pois apenas o embaixador faz aliados (dos reis) e separa aliados; o embaixador transaciona aquele negócio pelo qual (os reis) são desunidos ou não.` },
        { id: 'cm-7-67', number: 'Verso 67', text: `Com respeito aos assuntos, que o (embaixador) explore a expressão do semblante, os gestos e ações do (rei estrangeiro) através dos gestos e ações dos seus (conselheiros) de confiança, e (descubra) os seus desígnios entre os seus servos.` },
        { id: 'cm-7-68', number: 'Verso 68', text: `Tendo aprendido exatamente (com o seu embaixador) os desígnios do rei estrangeiro, que (o rei) tome tais medidas que não tragam mal para si mesmo.` },
        { id: 'cm-7-69', number: 'Verso 69', text: `Que ele se estabeleça num país que seja aberto e tenha um clima seco, onde os grãos sejam abundantes, que seja principalmente (habitado) por Arianos, não sujeito a doenças epidêmicas (ou problemas semelhantes), e agradável, onde os vassalos sejam obedientes e o seu próprio (povo facilmente) encontre o seu sustento.` },
        { id: 'cm-7-70', number: 'Verso 70', text: `Que ele construa (lá) uma cidade, fazendo para a sua segurança uma fortaleza, protegida por um deserto, ou uma fortaleza construída de (pedra e) terra, ou uma protegida por água ou árvores, ou uma (formada por um acampamento de homens) armados ou um forte na colina.` },
        { id: 'cm-7-71', number: 'Verso 71', text: `Que ele faça todo o esforço para garantir um forte na colina, pois dentre todas essas (fortalezas mencionadas) um forte na colina distingue-se por muitas qualidades superiores.` },
        { id: 'cm-7-72', number: 'Verso 72', text: `As três primeiras dessas (várias espécies de fortalezas) são habitadas por feras selvagens, animais que vivem em buracos e animais aquáticos, as três últimas por macacos, homens, e deuses respectivamente.` },
        { id: 'cm-7-73', number: 'Verso 73', text: `Assim como os inimigos não ferem estes (seres, quando estão) abrigados por (suas) fortalezas, assim também os inimigos não (podem) ferir um rei que se refugiou no seu forte.` },
        { id: 'cm-7-74', number: 'Verso 74', text: `Um arqueiro, colocado num baluarte, é um oponente em batalha para cem (inimigos), cem para dez mil; portanto é prescrito (nos *Sastras* que um rei possua) uma fortaleza.` },
        { id: 'cm-7-75', number: 'Verso 75', text: `Que esse (forte) seja bem suprido com armas, dinheiro, grãos e bestas de carga, com *Brahmanas*, com artesãos, com engenhos, com forragem, e com água.` },
        { id: 'cm-7-76', number: 'Verso 76', text: `Que ele mande construir para si mesmo, no centro dele, um palácio espaçoso, (bem) protegido, habitável em cada estação, resplandecente (com cal), suprido de água e árvores.` },
        { id: 'cm-7-77', number: 'Verso 77', text: `Habitado aquilo, que ele se case com uma consorte de igual casta (*varna*), que possua marcas auspiciosas (no seu corpo), e seja nascida de uma grande família, que seja encantadora e possua beleza e excelentes qualidades.` },
        { id: 'cm-7-78', number: 'Verso 78', text: `Que ele nomeie um sacerdote doméstico (*purohita*) e escolha sacerdotes oficiantes (*ritvig*); eles deverão realizar os seus ritos domésticos e os (sacrifícios) para os quais são requeridos três fogos.` },
        { id: 'cm-7-79', number: 'Verso 79', text: `Um rei deve oferecer vários sacrifícios (*Srauta*) nos quais taxas liberais (são distribuídas), e a fim de adquirir mérito, ele deve dar aos *Brahmanas* gozos e riquezas.` },
        { id: 'cm-7-80', number: 'Verso 80', text: `Que ele mande que a receita anual no seu reino seja coletada por (oficiais) de confiança, que ele obedeça à lei sagrada nas (suas transações com) o povo, e se comporte como um pai para com todos os homens.` },
        { id: 'cm-7-81', number: 'Verso 81', text: `Para os vários (ramos de negócios) que ele nomeie supervisores inteligentes; eles inspecionarão todos (os atos) daqueles homens que transacionam os seus negócios.` },
        { id: 'cm-7-82', number: 'Verso 82', text: `Que ele honre aqueles *Brahmanas* que retornaram da casa de seus professores (após estudar o Veda); pois aquele (dinheiro que é dado) aos *Brahmanas* é declarado ser um tesouro imperecível para os reis.` },
        { id: 'cm-7-83', number: 'Verso 83', text: `Nem ladrões nem inimigos podem tomá-lo, nem pode ser perdido; portanto, um estoque imperecível deve ser depositado por reis com *Brahmanas*.` },
        { id: 'cm-7-84', number: 'Verso 84', text: `A oferenda feita através da boca de um *Brahmana*, que não é derramada, nem cai (no chão), nem nunca perece, é muito mais excelente do que os *Agnihotras*.` },
        { id: 'cm-7-85', number: 'Verso 85', text: `Um presente a alguém que não é um *Brahmana* (rende) a recompensa comum; (um presente) a alguém que se autodenomina um *Brahmana*, uma dupla (recompensa); um presente a um *Brahmana* bem lido, uma recompensa cem mil vezes maior; (um presente) a alguém que conhece o Veda e os *Angas* (*Vedaparaga*), (uma recompensa) sem fim.` },
        { id: 'cm-7-86', number: 'Verso 86', text: `Pois de acordo com as qualidades particulares do recebedor e de acordo com a fé (do doador) uma pequena ou uma grande recompensa será obtida por um presente no outro mundo.` },
        { id: 'cm-7-87', number: 'Verso 87', text: `Um rei que, enquanto protege o seu povo, é desafiado por (inimigos), sejam eles iguais em força, ou mais fortes, ou mais fracos, não deve recuar da batalha, lembrando-se do dever dos *Kshatriyas*.` },
        { id: 'cm-7-88', number: 'Verso 88', text: `Não recuar em batalha, proteger o povo, honrar os *Brahmanas*, é o melhor meio para um rei assegurar a felicidade.` },
        { id: 'cm-7-89', number: 'Verso 89', text: `Aqueles reis que, buscando matar uns aos outros em batalha, lutam com o máximo esforço e não recuam, vão para o céu.` },
        { id: 'cm-7-90', number: 'Verso 90', text: `Quando ele luta com os seus inimigos em batalha, que ele não ataque com armas escondidas (em madeira), nem com (aquelas que são) farpadas, envenenadas, ou cujas pontas estejam em chamas de fogo.` },
        { id: 'cm-7-91', number: 'Verso 91', text: `Que ele não ataque alguém que (em fuga) escalou uma eminência, nem um eunuco, nem alguém que junta as palmas das suas mãos (em súplica), nem alguém que (foge) com o cabelo voando, nem alguém que se senta, nem alguém que diz 'Sou teu';` },
        { id: 'cm-7-92', number: 'Verso 92', text: `Nem alguém que dorme, nem alguém que perdeu a sua cota de malha, nem alguém que está nu, nem alguém que está desarmado, nem alguém que observa sem tomar parte na luta, nem alguém que está lutando com outro (inimigo);` },
        { id: 'cm-7-93', number: 'Verso 93', text: `Nem alguém cujas armas estão quebradas, nem alguém afligido (com tristeza), nem alguém que foi gravemente ferido, nem alguém que está com medo, nem alguém que se virou para fugir; (mas em todos estes casos que ele) se lembre do dever (dos guerreiros honrados).` },
        { id: 'cm-7-94', number: 'Verso 94', text: `Mas o (*Kshatriya*) que é morto em batalha, enquanto recua por medo, toma sobre si mesmo todo o pecado de seu mestre, qualquer que (possa ser);` },
        { id: 'cm-7-95', number: 'Verso 95', text: `E qualquer mérito (que um homem) que é morto em fuga possa ter ganhado para o próximo (mundo), tudo isso o seu mestre toma.` },
        { id: 'cm-7-96', number: 'Verso 96', text: `Carruagens e cavalos, elefantes, guarda-sóis, dinheiro, grãos, gado, mulheres, toda sorte de bens (comercializáveis) e metais sem valor pertencem a quem os toma (individualmente) conquistando (o possuidor).` },
        { id: 'cm-7-97', number: 'Verso 97', text: `Um texto do Veda (declara) que (os soldados) apresentarão uma porção escolhida (do espólio) ao rei; o que não foi tomado individualmente, deve ser distribuído pelo rei entre todos os soldados.` },
        { id: 'cm-7-98', number: 'Verso 98', text: `Assim foi declarada a lei primordial e irrepreensível para guerreiros; desta lei um *Kshatriya* não deve desviar-se, quando ele ataca os seus inimigos em batalha.` },
        { id: 'cm-7-99', number: 'Verso 99', text: `Que ele se esforce para ganhar o que ele ainda não ganhou; o que ele ganhou que ele preserve cuidadosamente; que ele aumente o que ele preserva, e o que ele aumentou que ele conceda a homens dignos.` },
        { id: 'cm-7-100', number: 'Verso 100', text: `Que ele saiba que estes são os quatro meios para assegurar os objetivos da (existência) humana; que ele, sem nunca se cansar, empregue-os adequadamente.` },
        { id: 'cm-7-101', number: 'Verso 101', text: `O que ele (ainda) não ganhou, que ele busque (ganhar) por (seu) exército; o que ele ganhou, que ele proteja com cuidadosa atenção; o que ele protegeu, que ele aumente por (vários modos de) aumentá-lo; e o que ele aumentou, que ele conceda liberalmente (a homens dignos).` },
        { id: 'cm-7-102', number: 'Verso 102', text: `Que ele esteja sempre pronto para atacar, a sua proeza constantemente exibida, e os seus segredos constantemente ocultados, e que ele constantemente explore as fraquezas do seu inimigo.` },
        { id: 'cm-7-103', number: 'Verso 103', text: `Daquele que está sempre pronto para atacar, o mundo inteiro tem temor; que ele portanto submeta todas as criaturas a si mesmo até mesmo pelo emprego da força.` },
        { id: 'cm-7-104', number: 'Verso 104', text: `Que ele aja sempre sem dissimulação, e em nenhum caso traiçoeiramente; guardando-se cuidadosamente, que ele sempre sonde a traição que os seus inimigos empregam.` },
        { id: 'cm-7-105', number: 'Verso 105', text: `O seu inimigo não deve conhecer as suas fraquezas, mas ele deve conhecer as fraquezas do seu inimigo; como a tartaruga (esconde os seus membros), assim também que ele assegure os membros (do seu governo contra a traição), que ele proteja os seus próprios pontos fracos.` },
        { id: 'cm-7-106', number: 'Verso 106', text: `Que ele planeje os seus empreendimentos (meditando pacientemente) como uma garça; como um leão, que ele coloque a sua força em ação; como um lobo, que ele arrebate (a sua presa); como uma lebre, que ele dê a volta em retirada.` },
        { id: 'cm-7-107', number: 'Verso 107', text: `Quando ele está assim engajado em conquista, que ele subjugue todos os oponentes que possa encontrar, pelos (quatro) expedientes, conciliação e o restante.` },
        { id: 'cm-7-108', number: 'Verso 108', text: `Se eles não puderem ser detidos pelos três primeiros expedientes, então que ele, vencendo-os apenas pela força, gradualmente os traga à sujeição.` },
        { id: 'cm-7-109', number: 'Verso 109', text: `Entre os quatro expedientes, conciliação e o restante, os instruídos sempre recomendam a conciliação e (o emprego da) força para a prosperidade dos reinos.` },
        { id: 'cm-7-110', number: 'Verso 110', text: `Como o capinador arranca as ervas daninhas e preserva o milho, assim também que o rei proteja o seu reino e destrua os seus oponentes.` },
        { id: 'cm-7-111', number: 'Verso 111', text: `Aquele rei que por tolice oprime precipitadamente o seu reino, (será), juntamente com os seus parentes, em breve privado da sua vida e do seu reino.` },
        { id: 'cm-7-112', number: 'Verso 112', text: `Assim como as vidas das criaturas vivas são destruídas atormentando os seus corpos, assim também as vidas dos reis são destruídas pela sua opressão aos seus reinos.` },
        { id: 'cm-7-113', number: 'Verso 113', text: `No governo do seu reino que ele sempre observe as (seguintes) regras; pois um rei que governa bem o seu reino, facilmente prospera.` },
        { id: 'cm-7-114', number: 'Verso 114', text: `Que ele coloque uma companhia de soldados, comandada (por um oficial de confiança), no meio de duas, três, cinco ou centenas de vilas, (para ser) uma proteção do reino.` },
        { id: 'cm-7-115', number: 'Verso 115', text: `Que ele nomeie um senhor sobre (cada) vila, bem como senhores de dez vilas, senhores de vinte, senhores de cem, e senhores de mil.` },
        { id: 'cm-7-116', number: 'Verso 116', text: `O próprio senhor de uma vila informará o senhor de dez vilas dos crimes cometidos na sua vila, e o governante de dez (fará o seu relatório) ao governante de vinte.` },
        { id: 'cm-7-117', number: 'Verso 117', text: `Mas o governante de vinte relatará todas essas (questões) ao senhor de cem, e o senhor de cem dará ele mesmo a informação ao senhor de mil.` },
        { id: 'cm-7-118', number: 'Verso 118', text: `Aqueles (artigos) que os aldeões deveriam fornecer diariamente ao rei, tais como comida, bebida, e lenha, o senhor de uma vila os obterá.` },
        { id: 'cm-7-119', number: 'Verso 119', text: `O governante de dez (vilas) desfrutará de um *kula* (tanta terra quanta é suficiente para uma família), o governante de vinte, cinco *kulas*, o superintendente de cem vilas (as receitas de) uma vila, o senhor de mil (as receitas de) uma cidade.` },
        { id: 'cm-7-120', number: 'Verso 120', text: `Os assuntos destes (oficiais), que estão conectados com as (suas) vilas e os seus negócios separados, outro ministro do rei inspecionará, (que deve ser) leal e nunca negligente;` },
        { id: 'cm-7-121', number: 'Verso 121', text: `E em cada cidade que ele nomeie um superintendente de todos os assuntos, elevado em posto, formidável, (semelhante) a um planeta entre as estrelas.` },
        { id: 'cm-7-122', number: 'Verso 122', text: `Que esse (homem) sempre visite pessoalmente, por turnos, todos esses (outros oficiais); que ele explore adequadamente o comportamento deles nos seus distritos através de espiões (nomeados para) cada um.` },
        { id: 'cm-7-123', number: 'Verso 123', text: `Pois os servos do rei, que são nomeados para proteger (o povo), geralmente se tornam canalhas que tomam a propriedade dos outros; que ele proteja os seus súditos contra tais (homens).` },
        { id: 'cm-7-124', number: 'Verso 124', text: `Que o rei confisque toda a propriedade daqueles (oficiais) que, mal-intencionados, possam tomar dinheiro dos litigantes, e os bana.` },
        { id: 'cm-7-125', number: 'Verso 125', text: `Para as mulheres empregadas no serviço real e para os servos braçais, que ele fixe uma manutenção diária, em proporção à sua posição e ao seu trabalho.` },
        { id: 'cm-7-126', number: 'Verso 126', text: `Um *pana* deve ser dado (diariamente) como salário aos mais baixos, seis aos mais altos, igualmente vestuário a cada seis meses e um *drona* de grãos a cada mês.` },
        { id: 'cm-7-127', number: 'Verso 127', text: `Tendo bem considerado (as taxas de) compra e (de) venda, (a extensão da) estrada, (a despesa para) comida e condimentos, os encargos de assegurar os bens, que o rei faça os comerciantes pagarem imposto.` },
        { id: 'cm-7-128', number: 'Verso 128', text: `Após (devida) consideração o rei sempre fixará no seu reino os deveres e impostos de tal maneira que tanto ele próprio quanto o homem que faz o trabalho recebam (sua devida) recompensa.` },
        { id: 'cm-7-129', number: 'Verso 129', text: `Assim como a sanguessuga, o bezerro, e a abelha tomam o seu alimento pouco a pouco, assim também o rei deve extrair do seu reino impostos anuais moderados.` },
        { id: 'cm-7-130', number: 'Verso 130', text: `Uma quinquagésima parte dos (incrementos em) gado e ouro pode ser tomada pelo rei, e a oitava, sexta, ou décima segunda parte das colheitas.` },
        { id: 'cm-7-131', number: 'Verso 131', text: `Ele pode também tomar a sexta parte das árvores, carne, mel, manteiga clarificada, perfumes, ervas (medicinais), substâncias usadas para dar sabor à comida, flores, raízes, e frutas;` },
        { id: 'cm-7-132', number: 'Verso 132', text: `De folhas, ervas de panela, grama, (objetos) feitos de cana, peles, de vasos de barro, e todos (os artigos) feitos de pedra.` },
        { id: 'cm-7-133', number: 'Verso 133', text: `Embora morrendo (de privação), um rei não deve cobrar imposto dos *Srotriyas*, e nenhum *Srotriya*, residindo no seu reino, deve perecer de fome.` },
        { id: 'cm-7-134', number: 'Verso 134', text: `O reino daquele rei, em cujos domínios um *Srotriya* definha com fome, em breve será afligido pela fome.` },
        { id: 'cm-7-135', number: 'Verso 135', text: `Tendo averiguado o seu aprendizado no Veda e (a pureza de) sua conduta, o rei providenciará para ele meios de subsistência em acordo com a lei sagrada, e o protegerá de todas as formas, como um pai (protege) o filho legítimo de seu corpo.` },
        { id: 'cm-7-136', number: 'Verso 136', text: `Quaisquer atos meritórios que (tal *Brahmana*) realize sob a plena proteção do rei, com isso a longevidade, riqueza, e reino do rei aumentam.` },
        { id: 'cm-7-137', number: 'Verso 137', text: `Que o rei faça com que os habitantes comuns do seu reino, que vivem do comércio, paguem anualmente alguma ninharia, que é chamada de imposto.` },
        { id: 'cm-7-138', number: 'Verso 138', text: `Mecânicos e artesãos, assim como *Sudras* que subsistem pelo trabalho manual, ele pode fazer trabalharem (para si próprio) um (dia) em cada mês.` },
        { id: 'cm-7-139', number: 'Verso 139', text: `Que ele não corte a sua própria raiz (por não cobrar impostos), nem a raiz de outros (homens) por ganância excessiva; pois ao cortar a sua própria raiz (ou a deles), ele torna a si mesmo ou a eles miseráveis.` },
        { id: 'cm-7-140', number: 'Verso 140', text: `Que o rei, tendo considerado cuidadosamente (cada) assunto, seja tanto enérgico quanto gentil; pois um rei que é tanto enérgico quanto gentil é altamente respeitado.` },
        { id: 'cm-7-141', number: 'Verso 141', text: `Quando ele estiver cansado com a inspeção dos negócios dos homens, que ele coloque naquele assento (da justiça) o seu ministro principal, (que deve ser) familiarizado com a lei, sábio, autocontrolado, e descendente de uma família (nobre).` },
        { id: 'cm-7-142', number: 'Verso 142', text: `Tendo assim organizado todos os assuntos (de) seu (governo), ele deverá zelosamente e cuidadosamente proteger os seus súditos.` },
        { id: 'cm-7-143', number: 'Verso 143', text: `Aquele (monarca) cujos súditos são levados por ladrões (*Dasyu*) do seu reino, enquanto eles gritam alto (por socorro), e ele e os seus servos estão (calmamente) apenas olhando, é um (rei) morto e não vivo.` },
        { id: 'cm-7-144', number: 'Verso 144', text: `O mais alto dever de um *Kshatriya* é proteger os seus súditos, pois o rei que desfruta das recompensas, há pouco mencionadas, está obrigado a (cumprir esse) dever.` },
        { id: 'cm-7-145', number: 'Verso 145', text: `Tendo se levantado na última vigília da noite, tendo realizado (o rito da) purificação pessoal, tendo, com a mente recolhida, oferecido oblações no fogo, e tendo adorado os *Brahmanas*, ele entrará no salão de audiências, o qual deve possuir as marcas (consideradas) auspiciosas (para uma habitação).` },
        { id: 'cm-7-146', number: 'Verso 146', text: `Demorando-se lá, ele gratificará todos os súditos (que vierem vê-lo por uma recepção gentil) e depois os dispensará; tendo dispensado os seus súditos, ele tomará conselho com os seus ministros.` },
        { id: 'cm-7-147', number: 'Verso 147', text: `Ascendendo ao topo de uma colina ou um terraço, (e) retirando-se (lá) para um lugar solitário, ou numa floresta solitária, que ele consulte com eles sem ser observado.` },
        { id: 'cm-7-148', number: 'Verso 148', text: `Aquele rei cujos planos secretos outras pessoas, (embora) reunidas (para o propósito), não descobrem, desfrutará (de) toda a terra, embora seja pobre em tesouro.` },
        { id: 'cm-7-149', number: 'Verso 149', text: `No momento da consulta, que ele mande remover idiotas, os mudos, os cegos, e os surdos, animais, homens muito idosos, mulheres, bárbaros, os doentes, e aqueles deficientes de membros.` },
        { id: 'cm-7-150', number: 'Verso 150', text: `(Tais pessoas) desprezíveis, igualmente animais, e particularmente mulheres, traem o conselho secreto; por essa razão ele deve ser cuidadoso com respeito a eles.` },
        { id: 'cm-7-151', number: 'Verso 151', text: `Ao meio-dia ou à meia-noite, quando as suas fadigas mentais e corporais tiverem passado, que ele delibere, quer consigo mesmo sozinho quer com os seus (ministros), sobre a virtude, o prazer, e a riqueza,` },
        { id: 'cm-7-152', number: 'Verso 152', text: `Sobre (reconciliar) a obtenção destes (objetivos) que são opostos uns aos outros, sobre conceder as suas filhas em casamento, e sobre manter os seus filhos (longe do mal),` },
        { id: 'cm-7-153', number: 'Verso 153', text: `Sobre enviar embaixadores, sobre a conclusão de empreendimentos (já começados), sobre o comportamento (das mulheres no) seu harém, e sobre os feitos dos seus espiões.` },
        { id: 'cm-7-154', number: 'Verso 154', text: `Sobre o inteiro negócio óctuplo e as cinco classes (de espiões), sobre a boa vontade ou inimizade e a conduta do círculo (de vizinhos ele deve) cuidadosamente (refletir).` },
        { id: 'cm-7-155', number: 'Verso 155', text: `Sobre a conduta do (príncipe) do meio, sobre os feitos daquele que busca conquista, sobre o comportamento do (rei) neutro, e (sobre o) do inimigo (que ele) sedulamente (medite).` },
        { id: 'cm-7-156', number: 'Verso 156', text: `Estes (quatro) constituintes (*prakriti*, formam), brevemente (falando), a fundação do círculo (de vizinhos); além disso, oito outros são enumerados (nos Institutos de Política) e (assim) o (total) é declarado ser doze.` },
        { id: 'cm-7-157', number: 'Verso 157', text: `O ministro, o reino, a fortaleza, o tesouro, e o exército são cinco outros (elementos constituintes do círculo); pois, estes são mencionados em conexão com cada um (dos primeiros doze; assim o círculo inteiro consiste), brevemente (falando, de) setenta e duas (partes constituintes).` },
        { id: 'cm-7-158', number: 'Verso 158', text: `Que (o rei) considere como hostil o seu vizinho imediato e o partidário de (tal) inimigo, como amigável o vizinho imediato do seu inimigo, e como neutro (o rei) além desses dois.` },
        { id: 'cm-7-159', number: 'Verso 159', text: `Que ele vença todos eles por meio dos (quatro) expedientes, conciliação e o restante, (empregados) quer isoladamente quer conjuntamente, (ou) por bravura e política (apenas).` },
        { id: 'cm-7-160', number: 'Verso 160', text: `Que ele constantemente pense nas seis medidas da política real (*guna*, a saber) aliança, guerra, marcha, parada, divisão do exército, e busca de proteção.` },
        { id: 'cm-7-161', number: 'Verso 161', text: `Tendo cuidadosamente considerado o negócio (em mãos), que ele recorra a ficar quieto ou marchar, aliança ou guerra, dividir as suas forças ou buscar proteção (conforme o caso possa exigir).` },
        { id: 'cm-7-162', number: 'Verso 162', text: `Mas o rei deve saber que há dois tipos de alianças e de guerras, (igualmente dois) tanto de marcha quanto de ficar quieto, e duas (ocasiões para) buscar proteção.` },
        { id: 'cm-7-163', number: 'Verso 163', text: `Uma aliança que rende vantagens presentes e futuras, deve-se saber ser de duas descrições, (a saber) aquela quando se marcha junto (com um aliado) e o contrário (quando os aliados agem separadamente).` },
        { id: 'cm-7-164', number: 'Verso 164', text: `A guerra é declarada ser de dois tipos, (a saber) aquela que é empreendida na estação ou fora de estação, por si mesmo e para os seus próprios propósitos, e (aquela travada para vingar) uma ofensa feita a um amigo.` },
        { id: 'cm-7-165', number: 'Verso 165', text: `A marcha (para o ataque) é dita ser dupla, (a saber, aquela empreendida) por um sozinho quando uma questão urgente surgiu repentinamente, e (aquela empreendida) por um aliado a um amigo.` },
        { id: 'cm-7-166', number: 'Verso 166', text: `Ficar quieto é afirmado ser de dois tipos, (a saber, aquele incumbido) a alguém que foi gradualmente enfraquecido pelo destino ou em consequência de atos anteriores, e (aquele) em favor de um amigo.` },
        { id: 'cm-7-167', number: 'Verso 167', text: `Se o exército para (em um lugar) e o seu mestre (em outro) a fim de efetuar algum propósito, isso é chamado por aqueles familiarizados com as virtudes das medidas da política real, a dupla divisão das forças.` },
        { id: 'cm-7-168', number: 'Verso 168', text: `Buscar refúgio é declarado ser de dois tipos, (primeiro) com o propósito de obter uma vantagem quando se é assediado por inimigos, (segundo) a fim de se tornar conhecido entre os virtuosos (como o protegido de um rei poderoso).` },
        { id: 'cm-7-169', number: 'Verso 169', text: `Quando (o rei) sabe (que) em algum tempo futuro a sua superioridade (é) certa, e (que) no tempo presente (ele sofrerá) pouco dano, então que ele tenha recurso a medidas pacíficas.` },
        { id: 'cm-7-170', number: 'Verso 170', text: `Mas quando ele acha que todos os seus súditos estão extremamente contentes, e (que ele) mesmo (é) mais exaltado (em poder), então que ele faça a guerra.` },
        { id: 'cm-7-171', number: 'Verso 171', text: `Quando ele sabe que o seu próprio exército está de disposição alegre e forte, e (que o) do seu inimigo o inverso, então que ele marche contra o seu inimigo.` },
        { id: 'cm-7-172', number: 'Verso 172', text: `Mas se ele é muito fraco em carruagens e bestas de carga e em tropas, então que ele cuidadosamente fique quieto, gradualmente conciliando os seus inimigos.` },
        { id: 'cm-7-173', number: 'Verso 173', text: `Quando o rei sabe que o inimigo é mais forte em todos os aspectos, então que ele divida o seu exército e assim alcance o seu propósito.` },
        { id: 'cm-7-174', number: 'Verso 174', text: `Mas quando ele é muito facilmente atacável pelas forças do inimigo, então que ele rapidamente busque refúgio com um rei justo e poderoso.` },
        { id: 'cm-7-175', number: 'Verso 175', text: `Aquele (príncipe) que coagirá tanto os seus súditos (desleais) quanto o exército do inimigo, que ele sempre o sirva com todo esforço como a um Guru.` },
        { id: 'cm-7-176', number: 'Verso 176', text: `Quando, mesmo nessa (condição), ele vê (que) o mal é causado por (tal) proteção, que ele sem hesitação tenha recurso à guerra.` },
        { id: 'cm-7-177', number: 'Verso 177', text: `Por todos os (quatro) expedientes um príncipe político deve arranjar (os assuntos de forma) que nem amigos, nem neutros, nem inimigos sejam superiores a ele mesmo.` },
        { id: 'cm-7-178', number: 'Verso 178', text: `Que ele considere plenamente o futuro e os resultados imediatos de todos os empreendimentos, e os lados bons e maus de todas as (ações) passadas.` },
        { id: 'cm-7-179', number: 'Verso 179', text: `Aquele que conhece o bem e o mal (que resultarão dos seus atos) no futuro, é rápido em formar resoluções para o presente, e entende as consequências das (ações) passadas, não será conquistado.` },
        { id: 'cm-7-180', number: 'Verso 180', text: `Que ele arranje tudo de tal maneira que nenhum aliado, nenhum neutro ou inimigo possa feri-lo; essa é a suma da sabedoria política.` },
        { id: 'cm-7-181', number: 'Verso 181', text: `Mas se o rei empreende uma expedição contra um reino hostil, então que ele avance gradualmente, da seguinte maneira, contra a capital do seu inimigo.` },
        { id: 'cm-7-182', number: 'Verso 182', text: `Que o rei empreenda a sua marcha no belo mês de Margasirsha, ou em direção aos meses de Phalguna e Kaitra, de acordo com a (condição do seu) exército.` },
        { id: 'cm-7-183', number: 'Verso 183', text: `Mesmo em outros tempos, quando ele tem uma certa perspectiva de vitória, ou quando um desastre se abateu sobre o seu inimigo, ele pode avançar para atacá-lo.` },
        { id: 'cm-7-184', number: 'Verso 184', text: `Mas tendo devidamente arranjado (todos os assuntos) no seu (reino) original e o que se relaciona com a expedição, tendo assegurado uma base (para as suas operações) e tendo devidamente despachado os seus espiões;` },
        { id: 'cm-7-185', number: 'Verso 185', text: `Tendo limpado os três tipos de estradas, e (tendo tornado) o seu exército sêxtuplo (eficiente), que ele proceda sem pressa da maneira prescrita para a guerra contra a capital do inimigo.` },
        { id: 'cm-7-186', number: 'Verso 186', text: `Que ele esteja muito em guarda contra um amigo que secretamente serve o inimigo e contra (desertores) que retornam (do acampamento do inimigo); pois tais (homens são) os inimigos mais perigosos.` },
        { id: 'cm-7-187', number: 'Verso 187', text: `Que ele marche na sua estrada, perfilando (as suas tropas) como um bastão (isto é, em um oblongo), ou como uma carroça (isto é, em uma cunha), ou como um javali (isto é, em um losango), ou como um Makara (isto é, em dois triângulos, com os ápices unidos), ou como um alfinete (isto é, em uma longa linha), ou como um Garuda (isto é, em um romboide com asas amplamente estendidas).` },
        { id: 'cm-7-188', number: 'Verso 188', text: `De qualquer (lado) que ele apreenda perigo, nessa (direção) que ele estenda as suas tropas, e que ele mesmo sempre acampe em uma formação, com a forma de um lótus.` },
        { id: 'cm-7-189', number: 'Verso 189', text: `Que ele designe ao comandante em chefe, ao general (subordinado), (e aos oficiais superiores) lugares em todas as direções, e que ele vire a sua frente naquela direção de onde ele teme perigo.` },
        { id: 'cm-7-190', number: 'Verso 190', text: `Em todos os lados que ele coloque tropas de soldados, nos quais ele possa confiar, com os quais sinais tenham sido combinados, que sejam especialistas tanto em sustentar um ataque quanto em atacar, destemidos e leais.` },
        { id: 'cm-7-191', number: 'Verso 191', text: `Que ele faça um pequeno número de soldados lutar em ordem cerrada, a seu bel-prazer que ele estenda um grande número em fileiras soltas; ou que ele os faça lutar, arranjando (um pequeno número) na formação de agulha, (e um grande número) na formação de raio.` },
        { id: 'cm-7-192', number: 'Verso 192', text: `Em terreno plano que ele lute com carruagens e cavalos, em lugares cercados por água com barcos e elefantes, em (terreno) coberto com árvores e arbustos com arcos, em terreno acidentado com espadas, escudos, (e outras) armas.` },
        { id: 'cm-7-193', number: 'Verso 193', text: `(Homens nascidos em) Kurukshetra, Matsyas, Pankalas, e aqueles nascidos em Surasena, que ele os faça lutar na vanguarda da batalha, bem como (outros que são) altos e leves.` },
        { id: 'cm-7-194', number: 'Verso 194', text: `Após arranjar as suas tropas, ele deve encorajá-las (com um discurso) e inspecioná-las cuidadosamente; ele deve também notar o comportamento (dos soldados) quando eles engajam o inimigo.` },
        { id: 'cm-7-195', number: 'Verso 195', text: `Quando ele tiver trancado o seu inimigo (em uma cidade), que ele sente-se acampado, assedie o seu reino, e estrague continuamente a sua grama, comida, lenha, e água.` },
        { id: 'cm-7-196', number: 'Verso 196', text: `Igualmente que ele destrua os tanques, baluartes, e valas, e que ele assalte o (inimigo desprevenido) e o alarme à noite.` },
        { id: 'cm-7-197', number: 'Verso 197', text: `Que ele instigue à rebelião aqueles que estão abertos a tais instigações, que ele seja informado dos feitos do seu (inimigo), e, quando o destino for propício, que ele lute sem medo, tentando conquistar.` },
        { id: 'cm-7-198', number: 'Verso 198', text: `Ele deve (entretanto) tentar conquistar os seus inimigos por conciliação, por presentes (bem aplicados), e criando dissensão, usados quer separadamente quer conjuntamente, nunca por lutar, (se puder ser evitado).` },
        { id: 'cm-7-199', number: 'Verso 199', text: `Pois quando dois (príncipes) lutam, vitória e derrota na batalha são, como a experiência ensina, incertas; que ele portanto evite um engajamento.` },
        { id: 'cm-7-200', number: 'Verso 200', text: `(Mas) se mesmo aqueles três expedientes antes mencionados falharem, então que ele, esforçando-se devidamente, lute de tal maneira que possa conquistar completamente os seus inimigos.` },
        { id: 'cm-7-201', number: 'Verso 201', text: `Quando ele tiver obtido vitória, que ele devidamente adore os deuses e honre *Brahmanas* justos, que ele conceda isenções, e que ele faça promessas de segurança serem proclamadas.` },
        { id: 'cm-7-202', number: 'Verso 202', text: `Mas tendo plenamente averiguado os desejos de todos os (conquistados), que ele coloque lá um parente do (governante vencido no trono), e que ele imponha as suas condições.` },
        { id: 'cm-7-203', number: 'Verso 203', text: `Que ele torne autoritativos os (costumes) lícitos dos (habitantes), exatamente como são declarados (ser), e que ele honre o (novo rei) e os seus servos principais com presentes preciosos.` },
        { id: 'cm-7-204', number: 'Verso 204', text: `A apreensão de propriedade desejável que causa desprazer, e a sua distribuição que causa prazer, são ambas recomendáveis, (se forem) recorridas no tempo apropriado.` },
        { id: 'cm-7-205', number: 'Verso 205', text: `Todos os empreendimentos (neste) (mundo) dependem tanto do ordenamento do destino quanto do esforço humano; mas entre estes dois (os caminhos do) destino são insondáveis; no caso do trabalho do homem a ação é possível.` },
        { id: 'cm-7-206', number: 'Verso 206', text: `Ou (o rei, inclinado à conquista), considerando um amigo, ouro, e terra (como sendo) o resultado triplo (de uma expedição), pode, usando de cuidado diligente, fazer paz com (o seu inimigo) e retornar (ao seu reino).` },
        { id: 'cm-7-207', number: 'Verso 207', text: `Tendo prestado a devida atenção a qualquer rei no círculo (de estados vizinhos) que possa atacá-lo pela retaguarda, e ao seu apoiador que se opõe a este último, que (o conquistador) assegure o fruto da expedição do (príncipe a quem ataca), quer (ele possa ter se tornado) amigável quer (permanecido) hostil.` },
        { id: 'cm-7-208', number: 'Verso 208', text: `Ao ganhar ouro e terra um rei não cresce tanto em força quanto ao obter um amigo firme, (que), embora fraco, (possa tornar-se) poderoso no futuro.` },
        { id: 'cm-7-209', number: 'Verso 209', text: `Um amigo fraco (mesmo) é grandemente louvado, que é justo (e) grato, cujo povo está contente, que é apegado e perseverante nos seus empreendimentos.` },
        { id: 'cm-7-210', number: 'Verso 210', text: `Os sábios o declaram (ser) um inimigo mui perigoso, aquele que é sábio, de raça nobre, bravo, inteligente, liberal, grato, e firme.` },
        { id: 'cm-7-211', number: 'Verso 211', text: `Comportamento digno de um Ariano, conhecimento de homens, bravura, uma disposição compassiva, e grande liberalidade são as virtudes de um neutro (que pode ser cortejado).` },
        { id: 'cm-7-212', number: 'Verso 212', text: `Que o rei, sem hesitação, abandone por seu próprio bem mesmo um país (que é) salubre, fértil, e causando um aumento de gado.` },
        { id: 'cm-7-213', number: 'Verso 213', text: `Para tempos de necessidade que ele preserve a sua riqueza; à custa da sua riqueza que ele preserve a sua esposa; que ele em todos os eventos preserve a si mesmo mesmo por (abrir mão d)a sua esposa e (d)a sua riqueza.` },
        { id: 'cm-7-214', number: 'Verso 214', text: `Um (rei) sábio, vendo que todos os tipos de infortúnios o assaltam violentamente ao mesmo tempo, deve tentar todos (os quatro) expedientes, seja juntos ou separadamente, (a fim de salvar a si mesmo).` },
        { id: 'cm-7-215', number: 'Verso 215', text: `Sobre a pessoa que emprega os expedientes, sobre o negócio a ser realizado, e sobre todos os expedientes coletivamente, nestes três que ele pondere e se esforce para alcançar os seus fins.` },
        { id: 'cm-7-216', number: 'Verso 216', text: `Tendo assim consultado com os seus ministros sobre todas essas (questões), tendo feito exercício, e tendo se banhado depois, o rei pode entrar no harém ao meio-dia a fim de jantar.` },
        { id: 'cm-7-217', number: 'Verso 217', text: `Lá ele pode comer comida, (que tenha sido preparada) por (servos) fiéis e incorruptíveis que conhecem o tempo (apropriado) (para jantar), a qual tenha sido bem examinada (e santificada) por textos sagrados que destroem veneno.` },
        { id: 'cm-7-218', number: 'Verso 218', text: `Que ele misture toda a sua comida com remédios (que são) antídotos contra veneno, e que ele sempre seja cuidadoso em usar gemas que destroem veneno.` },
        { id: 'cm-7-219', number: 'Verso 219', text: `Fêmeas bem testadas cuja toilette e ornamentos tenham sido examinados, deverão atentamente servi-lo com leques, água, e perfumes.` },
        { id: 'cm-7-220', number: 'Verso 220', text: `De maneira semelhante que ele seja cuidadoso sobre as suas carruagens, cama, assento, banho, toilette, e todos os seus ornamentos.` },
        { id: 'cm-7-221', number: 'Verso 221', text: `Quando ele tiver jantado, ele pode se divertir com as suas esposas no harém; mas quando ele tiver se divertido, ele deve, no tempo devido, novamente pensar nos assuntos de estado.` },
        { id: 'cm-7-222', number: 'Verso 222', text: `Adornado (com as suas vestes de estado), que ele novamente inspecione os seus homens de luta, todas as suas carruagens e bestas de carga, as armas e equipamentos.` },
        { id: 'cm-7-223', number: 'Verso 223', text: `Tendo realizado as suas devoções do crepúsculo, que ele, bem armado, ouça em um aposento interno os feitos daqueles que fazem relatórios secretos e dos seus espiões.` },
        { id: 'cm-7-224', number: 'Verso 224', text: `Mas indo para outro aposento secreto e dispensando aquelas pessoas, ele pode entrar no harém, cercado por (servas) fêmeas, a fim de jantar novamente.` },
        { id: 'cm-7-225', number: 'Verso 225', text: `Tendo comido lá algo pela segunda vez, e tendo sido recriado pelo som da música, que ele vá descansar e levante-se no tempo adequado livre de fadiga.` },
        { id: 'cm-7-226', number: 'Verso 226', text: `Um rei que está com boa saúde deve observar estas regras; mas, se ele estiver indisposto, ele pode confiar todos estes (negócios) aos seus servos.` },
      ],
    },
  ],
};
